# Bridges for Purpose
ea:PlacementAssessment
    a owl:Class ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en, "Pre-Assessment"@en, "Threshold Knowledge Test"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:PlacementPurpose
            ]
        )
    ] ;
    rdfs:comment "Assessment conducted before instruction to establish a baseline or place students into appropriate instructional points."@en .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en, "Classroom Assessment"@en, "Educative Assessment"@en, "Formative Evaluation"@en, "Formative Feedback"@en ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [
                a owl:Restriction ;
                owl:onProperty ea:hasAssessmentPurpose ;
                owl:someValuesFrom ea:FormativePurpose
            ]
        )
    ] ;
    rdfs:comment "Ongoing in-process evaluation conducted during learning to provide feedback and modify instruction."@en .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Evaluation"@en, "Diagnostic Testing"@en ;
    rdfs:subClassOf ea:FormativeAssessment ;
